@Builder  
@AllArgsConstructor  
@ToString  
@Setter  
@Getter  
@SQLDelete(sql = &quot;UPDATE user SET delete_at = NOW() WHERE user_id = ?&quot;)  
@SQLRestriction(&quot;delete_at is null&quot;)  
public class User {  

    @Id  
    @Column(name =&quot;user_id&quot;)  
    @GeneratedValue(strategy = GenerationType.IDENTITY)  
