    @OneToMany( mappedBy = &quot;user&quot;, cascade = CascadeType.ALL,orphanRemoval = true)  
    @Builder.Default  
    private List&lt;Post&gt; posts= new ArrayList&lt;&gt;();  

    @OneToMany( mappedBy = &quot;user&quot;, cascade = CascadeType.ALL)  
    @Builder.Default  
