#!/bin/bash  

echo &quot;Stopping application on port 8080...&quot;  

PID=$(lsof -i :8080 -t)  

if [ -n &quot;$PID&quot; ]; then  
  echo &quot;Found process: $PID. Killing...&quot;  
  kill -15 &quot;$PID&quot;  
  sleep 5  

  if ps -p &quot;$PID&quot; &gt; /dev/null; then  
    echo &quot;Force killing process: $PID...&quot;  
    kill -9 &quot;$PID&quot;  
  fi  
