    }
}

class Rectangle implements Shape{  
    @Override  
    public void print() {  
        System.out.println(&quot;Rectangle Hello&quot;);  
    }  
    @Override  
    public void accept(Visitor visitor) {  
        visitor.visitRectangle(this); 
	   //더블 디스패치
